1	"use server";
2	
3	import { z } from "zod";
4	import { redirect } from "next/navigation";
5	import { revalidatePath } from "next/cache";
6	import { requireRole } from "@/lib/auth";
7	import { createClient } from "@/lib/supabase/server";
8	import { createAdminClient } from "@/lib/supabase/admin";
9	import { providerOnboardingSchema } from "@/lib/validation/schemas";
10	import { getBackgroundCheck } from "@/lib/integrations/background-check";
11	
12	const onboardingPayloadSchema = providerOnboardingSchema.extend({
13	  isAvailableNow: z.boolean().default(false),
14	});
15	
16	export type OnboardingInput = z.input<typeof onboardingPayloadSchema>;
17	
18	export interface OnboardingResult {
19	  ok?: true;
20	  error?: string;
21	  fieldErrors?: Record<string, string>;
22	}
23	
24	/**
25	 * Complete provider onboarding: validate, save the profile + economics, kick
26	 * off the (mock) background check, and leave the provider in `pending` for
27	 * admin approval (M4). Writes via the service-role client scoped to the caller's
28	 * own id, so privileged columns (status/rating) are set deliberately here and
29	 * the provider can't change them directly (see providers_guard_privileged).
30	 */
31	export async function completeOnboarding(
32	  input: OnboardingInput,
33	): Promise<OnboardingResult> {
34	  const profile = await requireRole("provider");
35	
36	  const parsed = onboardingPayloadSchema.safeParse(input);
37	  if (!parsed.success) {
38	    const fieldErrors: Record<string, string> = {};
39	    for (const issue of parsed.error.issues) {
40	      const key = String(issue.path[0] ?? "");
41	      if (key && !fieldErrors[key]) fieldErrors[key] = issue.message;
42	    }
43	    return { error: "Please check the highlighted fields.", fieldErrors };
44	  }
45	
46	  const d = parsed.data;
47	  const bgCheck = getBackgroundCheck();
48	  const { checkRef, status: bgStatus } = await bgCheck.initiate({
49	    providerId: profile.id,
50	  });
51	
52	  const admin = createAdminClient();
53	  const { error } = await admin
54	    .from("providers")
55	    .update({
56	      display_name: d.displayName,
57	      bio: d.bio,
58	      voice_intro_path: d.voiceIntroPath ?? null,
59	      languages: d.languages,
60	      topics: d.topics,
61	      price_block_15_cents: d.priceBlock15Cents,
62	      price_block_30_cents: d.priceBlock30Cents,
63	      price_block_45_cents: d.priceBlock45Cents,
64	      overage_per_min_cents: d.overagePerMinCents,
65	      is_available_now: d.isAvailableNow,
66	      bg_check_ref: checkRef,
67	      bg_check_status: bgStatus,
68	      status: "pending",
69	    })
70	    .eq("id", profile.id);
71	
72	  if (error) {
73	    return { error: "We couldn't save your profile. Please try again." };
74	  }
75	
76	  revalidatePath("/provider/dashboard");
77	  redirect("/provider/dashboard?onboarded=1");
78	}
79	
80	/** Decline (cancel) an incoming booking made with the signed-in provider. */
81	export async function declineBooking(
82	  bookingId: string,
83	): Promise<{ ok: boolean }> {
84	  const profile = await requireRole("provider");
85	  const supabase = await createClient();
86	  const { error } = await supabase
87	    .from("bookings")
88	    .update({ status: "cancelled" })
89	    .eq("id", bookingId)
90	    .eq("provider_id", profile.id);
91	  if (error) return { ok: false };
92	  revalidatePath("/provider/dashboard");
93	  return { ok: true };
94	}
95	
96	/** Toggle the provider's "Available now" state (own row, RLS-enforced). */
97	export async function setAvailability(
98	  isAvailableNow: boolean,
99	): Promise<{ ok: boolean }> {
100	  const profile = await requireRole("provider");
101	  const supabase = await createClient();
102	  const { error } = await supabase
103	    .from("providers")
104	    .update({ is_available_now: isAvailableNow })
105	    .eq("id", profile.id);
106	  if (error) return { ok: false };
107	  revalidatePath("/provider/dashboard");
108	  return { ok: true };
109	}
